{
  "items": [
    {
      "name": "Finsupp.zero_update",
      "type": " {α : Type u_1} {M : Type u_4} [Zero M] (a : α) (b : M) : Finsupp.update 0 a b = fun₀ | a => b",
      "module": "Mathlib.Data.Finsupp.Single"
    },
    {
      "name": "Finsupp.update_eq_erase_add_single",
      "type": " {ι : Type u_1} {M : Type u_3} [AddZeroClass M] (f : ι →₀ M) (a : ι) (b : M) : f.update a b = Finsupp.erase a f + fun₀ | a => b",
      "module": "Mathlib.Algebra.Group.Finsupp"
    },
    {
      "name": "Finsupp.update_eq_single_add_erase",
      "type": " {ι : Type u_1} {M : Type u_3} [AddZeroClass M] (f : ι →₀ M) (a : ι) (b : M) : f.update a b = (fun₀ | a => b) + Finsupp.erase a f",
      "module": "Mathlib.Algebra.Group.Finsupp"
    },
    {
      "name": "Finsupp.update_eq_add_single",
      "type": " {ι : Type u_1} {M : Type u_3} [AddZeroClass M] {f : ι →₀ M} {a : ι} (h : f a = 0) (b : M) : f.update a b = f + fun₀ | a => b",
      "module": "Mathlib.Algebra.Group.Finsupp"
    },
    {
      "name": "Finsupp.update_eq_single_add",
      "type": " {ι : Type u_1} {M : Type u_3} [AddZeroClass M] {f : ι →₀ M} {a : ι} (h : f a = 0) (b : M) : f.update a b = (fun₀ | a => b) + f",
      "module": "Mathlib.Algebra.Group.Finsupp"
    },
    {
      "name": "Finsupp.update_eq_sub_add_single",
      "type": " {ι : Type u_1} {G : Type u_6} [AddGroup G] (f : ι →₀ G) (a : ι) (b : G) : f.update a b = (f - fun₀ | a => f a) + fun₀ | a => b",
      "module": "Mathlib.Algebra.Group.Finsupp"
    },
    {
      "name": "Polynomial.homogenize_monomial",
      "type": " {R : Type u_1} [CommSemiring R] {m n : ℕ} (h : m ≤ n) (r : R) : ((Polynomial.monomial m) r).homogenize n = (MvPolynomial.monomial fun₀ | 0 => m | 1 => n - m) r",
      "module": "Mathlib.Algebra.Polynomial.Homogenize"
    }
  ]
}
